<template>
  <GeoLocationField
    v-if="controlType === 'geolocation'"
    :field="field"
    :model-value="modelValue"
    @update:model-value="$emit('update:modelValue', $event)"
  />

  <TableMultiSelectField
    v-else-if="controlType === 'table-multiselect'"
    :field="field"
    :model-value="modelValue"
    @update:model-value="$emit('update:modelValue', $event)"
  />

  <div v-else-if="controlType === 'attach'">
    <label class="mb-1.5 block text-xs text-ink-gray-5">{{ t(field.label) }}</label>
    <div v-if="modelValue" class="flex items-center gap-3 rounded-lg border p-2 dark:border-gray-800">
      <img
        v-if="isImageField"
        :src="modelValue"
        class="h-12 w-12 flex-shrink-0 rounded object-cover"
      />
      <FeatherIcon v-else name="paperclip" class="h-5 w-5 flex-shrink-0 text-gray-400" />
      <a
        :href="modelValue"
        target="_blank"
        rel="noopener"
        class="min-w-0 flex-1 truncate text-sm text-gray-700 hover:underline dark:text-gray-300"
      >
        {{ fileName }}
      </a>
      <Tooltip :text="t('Remove file')">
        <button
          type="button"
          class="flex h-7 w-7 flex-shrink-0 items-center justify-center rounded text-gray-400 hover:bg-gray-100 hover:text-red-500 dark:hover:bg-gray-800"
          @click="$emit('update:modelValue', null)"
        >
          <FeatherIcon name="x" class="h-4 w-4" />
        </button>
      </Tooltip>
    </div>
    <FileUploader
      v-else
      :file-types="isImageField ? 'image/*' : undefined"
      :upload-args="{ doctype, docname, private: false }"
      @success="(file) => $emit('update:modelValue', file.file_url)"
    >
      <template #default="{ uploading, progress, openFileSelector }">
        <Button variant="outline" :loading="uploading" @click="openFileSelector">
          {{ uploading ? t('Uploading {0}%', [progress]) : isImageField ? t('Attach Image') : t('Attach File') }}
        </Button>
      </template>
    </FileUploader>
  </div>

  <FormControl
    v-else-if="controlType === 'select'"
    type="select"
    variant="outline"
    :placeholder="t('Select option')"
    :class="['[&_[data-slot=trigger]]:w-full', FIELD_HOVER_CLASS]"
    :label="t(field.label)"
    :required="!!field.reqd"
    :options="selectOptions"
    :description="t(field.description) || undefined"
    :disabled="readOnly"
    :model-value="modelValue"
    @update:model-value="$emit('update:modelValue', $event)"
  />
  <FormControl
    v-else-if="controlType === 'checkbox'"
    type="checkbox"
    :label="t(field.label)"
    :description="t(field.description) || undefined"
    :disabled="readOnly"
    :model-value="!!modelValue"
    @update:model-value="$emit('update:modelValue', $event ? 1 : 0)"
  />
  <FormControl
    v-else-if="controlType === 'textarea'"
    type="textarea"
    variant="outline"
    :class="FIELD_HOVER_CLASS"
    :label="t(field.label)"
    :required="!!field.reqd"
    :description="t(field.description) || undefined"
    :disabled="readOnly"
    :model-value="modelValue"
    @update:model-value="$emit('update:modelValue', $event)"
  />
  <div v-else-if="isUserLink">
    <FormControl
      type="text"
      variant="outline"
      :class="FIELD_HOVER_CLASS"
      :label="t(field.label)"
      :required="!!field.reqd"
      :description="t(field.description) || undefined"
      :disabled="readOnly"
      :model-value="modelValue"
      @update:model-value="$emit('update:modelValue', $event)"
    >
      <template v-if="modelValue" #suffix>
        <UserLinkHoverCard :user="modelValue">
          <FeatherIcon name="user" class="h-4 w-4 text-gray-400" />
        </UserLinkHoverCard>
      </template>
    </FormControl>
  </div>
  <SignatureField
    v-else-if="controlType === 'signature'"
    :field="field"
    :model-value="modelValue"
    :read-only="readOnly"
    @update:model-value="$emit('update:modelValue', $event)"
  />
  <LinkField
    v-else-if="controlType === 'link'"
    :field="field"
    :model-value="modelValue"
    :read-only="readOnly"
    :link-query="linkQuery"
    :reference-doctype="doctype"
    @update:model-value="$emit('update:modelValue', $event)"
  />
  <FormControl
    v-else
    :type="controlType"
    variant="outline"
    :class="FIELD_HOVER_CLASS"
    :label="t(field.label)"
    :required="!!field.reqd"
    :description="t(field.description) || undefined"
    :disabled="readOnly"
    :model-value="modelValue"
    @update:model-value="$emit('update:modelValue', toFieldValue($event))"
  />
</template>

<script setup>
import { computed } from 'vue'
import { FormControl, FileUploader, Button, FeatherIcon, Tooltip } from 'frappe-ui'
import UserLinkHoverCard from '@/components/UserLinkHoverCard.vue'
import GeoLocationField from '@/components/GeoLocationField.vue'
import TableMultiSelectField from '@/components/TableMultiSelectField.vue'
import LinkField from '@/components/LinkField.vue'
import SignatureField from '@/components/SignatureField.vue'
import { evaluateDependsOn } from '@/data/dependsOn'
import { t } from '@/data/i18n'

const props = defineProps({
  field: { type: Object, required: true },
  modelValue: { default: null },
  doctype: { type: String, default: null },
  docname: { type: String, default: null },
  // Desk's set_query for a Link field: { filters } and/or { query }.
  linkQuery: { type: Object, default: null },
  // Desk conditions on the form (parent doc and, in a child row, the row).
  doc: { type: Object, default: null },
  parentDoc: { type: Object, default: null },
})
defineEmits(['update:modelValue'])

// A number box gives text ("2"); Desk sends a real number, and server code
// doing arithmetic with it (e.g. Household's pending members = total -
// added) failed on text with a TypeError. Empty stays empty.
function toFieldValue(value) {
  if (controlType.value !== 'number') return value
  if (value === '' || value == null) return null
  const n = props.field.fieldtype === 'Int' ? parseInt(value, 10) : parseFloat(value)
  return Number.isNaN(n) ? null : n
}

// Desk's read_only / read_only_depends_on: shown, but not editable - e.g.
// Age, Village and other values the form or server fills in. Read-only
// fields used to be ordinary editable boxes here.
const readOnly = computed(
  () =>
    !!props.field.read_only ||
    (!!props.field.read_only_depends_on && evaluateDependsOn(props.field.read_only_depends_on, props.doc || {}, props.parentDoc || props.doc)),
)

const controlType = computed(() => {
  switch (props.field.fieldtype) {
    case 'Select':
      return 'select'
    case 'Check':
      return 'checkbox'
    case 'Text':
    case 'Small Text':
    case 'Long Text':
    case 'Text Editor':
    case 'Code':
      return 'textarea'
    case 'Int':
    case 'Float':
    case 'Currency':
    case 'Percent':
      return 'number'
    case 'Date':
      return 'date'
    case 'Datetime':
      return 'datetime-local'
    case 'Time':
      return 'time'
    case 'Signature':
      return 'signature'
    case 'Link':
      return props.field.options === 'User' ? 'text' : 'link'
    case 'Password':
      return 'password'
    case 'Attach':
    case 'Attach Image':
      return 'attach'
    case 'Geolocation':
      return 'geolocation'
    case 'Table MultiSelect':
      return 'table-multiselect'
    default:
      return 'text'
  }
})

// A light tint on hover, since the "outline" variant is plain white at
// rest and gave no visual feedback at all on hover besides the border -
// targets the control's own rendered element (input/textarea/select
// trigger) from outside, the same arbitrary-selector trick already used
// for the select trigger's width.
const FIELD_HOVER_CLASS =
  '[&_input]:hover:!bg-forest-50 [&_textarea]:hover:!bg-forest-50 [&_[data-slot=trigger]]:hover:!bg-forest-50 dark:[&_input]:hover:!bg-forest-900/20 dark:[&_textarea]:hover:!bg-forest-900/20 dark:[&_[data-slot=trigger]]:hover:!bg-forest-900/20'

const isImageField = computed(() => props.field.fieldtype === 'Attach Image')
const isUserLink = computed(() => props.field.fieldtype === 'Link' && props.field.options === 'User')

const fileName = computed(() => {
  if (!props.modelValue) return ''
  try {
    return decodeURIComponent(props.modelValue.split('/').pop())
  } catch {
    return props.modelValue.split('/').pop()
  }
})

const selectOptions = computed(() => {
  const raw = props.field.options || ''
  return raw
    .split('\n')
    .map((v) => v.trim())
    .filter(Boolean)
    // Shown in the user's language; the English option is what's stored.
    .map((v) => ({ label: t(v), value: v }))
})

</script>
